#!/usr/bin/env bash
# PR-only one-off verification for issue #39 (remove before merge).
#
# Proves the corpus fixture committed at
# ColorComposerCore/Tests/ColorComposerCoreTests/Fixtures/parity/v1/corpus.json
# is byte-identical to the one published by viamin/color_matching
# (priv/parity/v1/corpus.json, generated by ColorMatching.Parity.Corpus —
# the corpus deliverable this issue depends on).
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
FIXTURE="$REPO_ROOT/ColorComposerCore/Tests/ColorComposerCoreTests/Fixtures/parity/v1/corpus.json"
UPSTREAM_URL="https://raw.githubusercontent.com/viamin/color_matching/main/priv/parity/v1/corpus.json"

if [[ ! -f "$FIXTURE" ]]; then
  echo "FAIL: fixture missing: $FIXTURE"
  exit 1
fi

TMP="$(mktemp)"
trap 'rm -f "$TMP"' EXIT
curl -fsSL --connect-timeout 10 --max-time 30 "$UPSTREAM_URL" -o "$TMP"

if diff -u "$TMP" "$FIXTURE"; then
  echo "PASS: committed parity corpus is byte-identical to $UPSTREAM_URL"
  echo "sha256: $(shasum -a 256 "$FIXTURE" 2>/dev/null || sha256sum "$FIXTURE" | cut -d' ' -f1)"
else
  echo "FAIL: committed parity corpus differs from upstream — refresh it (docs/parity-corpus.md)"
  exit 1
fi
